<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { getResourceDetail, listResources, recordResourceInteraction } from '../api/resource';
import ResourceDetailRenderer from '../components/ResourceDetailRenderer.vue';
import DfsTraversalVisualizer from '../components/resource/DfsTraversalVisualizer.vue';
import SplitText from '../components/SplitText.vue';
import type { ResourceCard } from '../types';
import type { ResourceDetail } from '@/types/api';

type ResourceCategory = { type: ResourceCard['type']; label: string; eyebrow: string; description: string; icon: string; gradient: string; glow: string };
const CATEGORY_ORDER: ResourceCategory[] = [
  { type: 'lecture', label: '个性化讲义', eyebrow: '理解与复习', description: '把课程知识整理成可阅读、可回看的个性化讲义。', icon: '▤', gradient: 'linear-gradient(135deg, rgba(34,154,133,.92), rgba(111,207,185,.55))', glow: 'rgba(34,154,133,.3)' },
  { type: 'mindmap', label: '知识思维导图', eyebrow: '结构与关联', description: '从知识点关系出发，建立清晰的学习地图。', icon: '⌘', gradient: 'linear-gradient(135deg, rgba(83,111,205,.92), rgba(149,170,255,.55))', glow: 'rgba(83,111,205,.3)' },
  { type: 'quiz', label: '分层练习题', eyebrow: '练习与诊断', description: '用分层练习发现薄弱点，并把结果回流到路径。', icon: '✓', gradient: 'linear-gradient(135deg, rgba(230,150,72,.96), rgba(255,206,124,.58))', glow: 'rgba(230,150,72,.3)' },
  { type: 'codelab', label: '代码实验', eyebrow: '实践与迁移', description: '通过代码实验把概念变成可运行的步骤。', icon: '</>', gradient: 'linear-gradient(135deg, rgba(176,91,132,.94), rgba(239,161,194,.58))', glow: 'rgba(176,91,132,.3)' },
  { type: 'flowchart', label: '流程图', eyebrow: '流程与决策', description: '把复杂流程压缩成可追踪的判断节点。', icon: '↗', gradient: 'linear-gradient(135deg, rgba(111,102,181,.94), rgba(193,180,255,.58))', glow: 'rgba(111,102,181,.3)' },
  { type: 'reading', label: '拓展阅读', eyebrow: '延伸与拓展', description: '基于课程证据补充当前阶段的延伸阅读。', icon: '◫', gradient: 'linear-gradient(135deg, rgba(57,132,176,.94), rgba(143,211,244,.58))', glow: 'rgba(57,132,176,.3)' },
];

const resources = ref<ResourceCard[]>([]); const selected = ref<ResourceDetail | null>(null); const activeCategoryIndex = ref(0); const loading = ref(true); const detailLoading = ref(false); const errorMessage = ref(''); const progress = ref(0); const rating = ref(0); const interactionNote = ref('');
const categoryResourceCount = computed(() => { const counts = new Map<ResourceCard['type'], number>(); resources.value.forEach((resource) => counts.set(resource.type, (counts.get(resource.type) || 0) + 1)); return counts; });
const activeCategory = computed(() => CATEGORY_ORDER[activeCategoryIndex.value]); const activeResources = computed(() => resources.value.filter((resource) => resource.type === activeCategory.value.type)); const activeResourceNames = computed(() => activeResources.value.map((resource) => resource.title)); const activeResourcePreview = computed(() => activeResourceNames.value.slice(0, 3)); const activeResourceRemainder = computed(() => Math.max(activeResourceNames.value.length - activeResourcePreview.value.length, 0)); const categoryCount = (type: ResourceCard['type']) => categoryResourceCount.value.get(type) || 0;
const showDfsVisualizer = computed(() => {
  const detail = selected.value;
  const searchable = [detail?.title, detail?.summary, detail?.content, ...(detail?.knowledge_points ?? [])].filter(Boolean).join(' ');
  return /(?:\bDFS\b|深度优先(?:搜索|遍历)?)/i.test(searchable);
});
const isLectureResource = computed(() => {
  const type = selected.value?.resource_type || selected.value?.type;
  return type === 'lecture';
});
const visibleCategoryEntries = computed(() => [-1, 0, 1, 2].map((offset) => { const index = (activeCategoryIndex.value + offset + CATEGORY_ORDER.length) % CATEGORY_ORDER.length; return { category: CATEGORY_ORDER[index], index }; }));
const setCategory = (index: number) => { activeCategoryIndex.value = (index + CATEGORY_ORDER.length) % CATEGORY_ORDER.length; selected.value = null; interactionNote.value = ''; }; const shiftCategory = (delta: number) => setCategory(activeCategoryIndex.value + delta);
const loadResources = async () => { loading.value = true; errorMessage.value = ''; try { const data = await listResources({ page: 1, size: 50 }); resources.value = data.items.filter((resource) => resource.type !== 'animation_script'); const firstPopulated = CATEGORY_ORDER.findIndex((category) => categoryCount(category.type) > 0); if (firstPopulated >= 0) activeCategoryIndex.value = firstPopulated; } catch (error) { errorMessage.value = error instanceof Error ? error.message : '资源列表加载失败'; } finally { loading.value = false; } };
const openResource = async (resource: ResourceCard) => { detailLoading.value = true; interactionNote.value = ''; try { selected.value = await getResourceDetail(resource.id); const state = await recordResourceInteraction(resource.id, { action: 'view', progressPercent: progress.value }); progress.value = state.progress_percent ?? 0; rating.value = state.rating ?? 0; } catch (error) { errorMessage.value = error instanceof Error ? error.message : '资源详情加载失败'; } finally { detailLoading.value = false; } };
const updateProgress = async (value: number) => { if (!selected.value) return; progress.value = value; const action = value >= 100 ? 'complete' : 'start'; const state = await recordResourceInteraction(selected.value.resource_id || String(selected.value.id), { action, progressPercent: value }); const mastery = state.learning_update?.mastery_updates?.[0]; interactionNote.value = mastery ? `${mastery.knowledge_point} 掌握度 ${mastery.previous_score}% → ${mastery.mastery_score}%` : value >= 100 ? '已完成，本次学习行为已记录；重复提交不会重复加权。' : `学习进度已记录为 ${value}%`; };
const rateResource = async (value: number) => { if (!selected.value) return; rating.value = value; await recordResourceInteraction(selected.value.resource_id || String(selected.value.id), { action: 'rate', rating: value, progressPercent: progress.value }); interactionNote.value = `已记录 ${value} 星评价。`; }; onMounted(loadResources);
</script>

<template>
  <section class="resource-library ai-page-bg page-enter">
    <header class="resource-library__head"><div><span>PERSONALIZED LIBRARY / 资源分类浏览</span><SplitText tag="h1" text="你的学习资源空间" /><p>先按学习目的选择资源类型，再进入对应的资源包。每一类内容都保留画像依据、课程证据和安全审查结果。</p></div><div class="library-total" aria-label="资源总量"><strong>{{ resources.length }}</strong><span>个资源包</span></div></header>
    <p v-if="loading" class="library-state">正在同步资源库...</p><p v-else-if="errorMessage" class="library-state error-line">{{ errorMessage }}</p><p v-else-if="!resources.length" class="library-state">暂无资源，请先在资源生成页面创建个性化资源包。</p>
    <template v-else>
      <section class="category-stage" aria-label="资源类别选择"><button class="category-arrow" type="button" aria-label="上一个资源类别" @click="shiftCategory(-1)">‹</button><div class="category-rail"><button v-for="entry in visibleCategoryEntries" :key="entry.category.type" type="button" class="category-card" :class="{ active: entry.index === activeCategoryIndex, empty: categoryCount(entry.category.type) === 0 }" :style="{ '--category-gradient': entry.category.gradient, '--category-glow': entry.category.glow }" @click="setCategory(entry.index)"><div class="category-card__top"><b>{{ entry.category.icon }}</b></div><h2>{{ entry.category.label }}</h2></button></div><button class="category-arrow" type="button" aria-label="下一个资源类别" @click="shiftCategory(1)">›</button></section>
      <section class="category-caption" :style="{ '--category-glow': activeCategory.glow }"><div><span>当前分类 / {{ activeCategory.eyebrow }}</span><h2>{{ activeCategory.label }} <small>{{ categoryCount(activeCategory.type) }} 个资源包</small></h2><p>{{ activeCategory.description }}</p></div><div v-if="activeResourcePreview.length" class="category-caption__packs"><span>这里有：</span><strong v-for="name in activeResourcePreview" :key="name">{{ name }}</strong><em v-if="activeResourceRemainder">+{{ activeResourceRemainder }} 个</em></div><div v-else class="category-caption__empty">这个类别暂时还没有资源，去“资源生成”创建一份吧。</div></section>
      <section class="category-focus" :style="{ '--category-glow': activeCategory.glow }"><header class="category-focus__head"><div><span>EXPLORE {{ activeCategory.label.toUpperCase() }}</span><h2>{{ activeCategory.label }} 资源包</h2></div><small>点击任意资源包查看完整内容、课程依据和学习反馈</small></header><div v-if="activeResources.length" class="resource-pack-grid"><button v-for="resource in activeResources" :key="resource.id" type="button" class="resource-pack" @click="openResource(resource)"><div class="resource-pack__visual"><span>{{ activeCategory.label }}</span><b>{{ activeCategory.icon }}</b></div><div class="resource-pack__body"><div class="resource-pack__meta"><span>{{ resource.difficulty || '个性化' }}</span><span v-if="resource.minutes">{{ resource.minutes }} 分钟</span></div><h3>{{ resource.title }}</h3><p>{{ resource.subtitle }}</p><small>{{ resource.tags.slice(0, 2).join(' · ') }}</small></div><i>查看资源包 →</i></button></div><div v-else class="category-empty"><b>{{ activeCategory.icon }}</b><h3>还没有 {{ activeCategory.label }} 资源</h3><p>生成资源时选择 {{ activeCategory.label }}，它会出现在这里。</p></div></section>
    </template>
    <div v-if="selected || detailLoading" class="resource-dialog" role="dialog" aria-modal="true" @click.self="selected = null"><article class="resource-reader"><button class="resource-reader__close" type="button" aria-label="关闭资源详情" @click="selected = null">×</button><p v-if="detailLoading">正在读取资源详情...</p><template v-else-if="selected"><header><span>{{ selected.resource_type || selected.type }} · {{ selected.difficulty }}</span><h1>{{ selected.title }}</h1><p>{{ selected.personalized_reason || selected.summary }}</p></header><div class="resource-reader__meta"><span>预计 {{ selected.estimated_minutes || '—' }} 分钟</span><span>Safety {{ selected.safety.passed ? '通过' : '需复核' }}</span><span>置信度 {{ Math.round(selected.safety.confidence * 100) }}%</span></div><DfsTraversalVisualizer v-if="showDfsVisualizer && isLectureResource" />\n<ResourceDetailRenderer :detail="selected" /><section v-if="showDfsVisualizer && !isLectureResource" class="dfs-support-section"><header><span>辅助理解</span><h2>图结构与递归栈同步演示</h2><p>先完成当前类别的主要内容，再通过交互图解核对 DFS 的访问、入栈与回溯过程。</p></header><DfsTraversalVisualizer /></section><section class="evidence-list"><h2>课程知识依据</h2><article v-for="item in selected.evidence" :key="item.chunk_id || item.chunkId"><strong>{{ item.title }}</strong><p>{{ item.content }}</p><small>{{ item.source }} · {{ Math.round(item.score * 100) }}%</small></article></section><footer class="learning-actions"><div><strong>学习进度</strong><button v-for="value in [25, 50, 75, 100]" :key="value" :class="{ active: progress === value }" @click="updateProgress(value)">{{ value }}%</button></div><div><strong>资源评价</strong><button v-for="value in 5" :key="value" :class="{ active: rating >= value }" @click="rateResource(value)">★</button></div><p>{{ interactionNote }}</p></footer></template></article></div>
  </section>
</template>

<style scoped>
