.category-stage{position:relative;display:flex;align-items:stretch;gap:16px;margin:18px auto;max-width:1420px}.category-rail{display:grid;grid-template-columns:repeat(4,minmax(210px,1fr));gap:18px;flex:1;min-width:0}.category-card{min-height:294px;text-align:left;border:1px solid rgba(255,255,255,.52);border-radius:30px;padding:25px;color:#fff;background:var(--category-gradient);box-shadow:0 22px 42px -24px var(--category-glow),inset 0 1px rgba(255,255,255,.48);cursor:pointer;transition:transform .35s ease,box-shadow .35s ease,filter .35s ease,opacity .35s ease;display:flex;flex-direction:column}.category-card:hover,.category-card.active{transform:translateY(-9px) scale(1.015);box-shadow:0 32px 58px -24px var(--category-glow),inset 0 1px rgba(255,255,255,.68)}.category-card:not(.active){filter:saturate(.72);opacity:.78}.category-card.empty{opacity:.46}.category-card__top{display:flex;align-items:center;justify-content:flex-end}.category-card__top b{display:grid;place-items:center;width:58px;height:58px;border:1px solid rgba(255,255,255,.45);border-radius:18px;font-size:29px;letter-spacing:-.12em}.category-card h2{font-size:clamp(28px,3vw,40px);letter-spacing:-.055em;margin:auto 0 0;color:#fff}.category-arrow{flex:0 0 48px;align-self:center;width:48px;height:48px;border:1px solid rgba(31,54,49,.13);border-radius:50%;background:rgba(255,255,255,.74);color:var(--color-ink);font-size:34px;line-height:1;cursor:pointer;box-shadow:0 8px 22px rgba(31,54,49,.08);transition:transform .2s ease,background .2s ease}.category-arrow:hover{transform:scale(1.08);background:#fff}
