y-empty b{display:grid;place-items:center;width:58px;height:58px;border-radius:20px;margin:0 auto 14px;background:rgba(0,121,102,.08);color:var(--color-primary);font-size:27px}.category-empty h3{margin:0 0 8px;color:var(--color-ink)}.category-empty p{margin:0;font-size:13px}
.dfs-support-section{display:grid;gap:14px;margin-top:8px;border-top:1px solid rgba(31,54,49,.1);padding-top:22px}.dfs-support-section>header{display:grid;gap:5px}.dfs-support-section>header span{color:var(--color-primary);font-size:11px;font-weight:900;letter-spacing:.12em}.dfs-support-section>header h2{margin:0;font-size:20px}.dfs-support-section>header p{margin:0;color:rgba(31,54,49,.64);font-size:13px;line-height:1.65}.resource-dialog{position:fixed;inset:0;z-index:100;background:rgba(18,34,30,.58);display:grid;place-items:center;padding:28px}.resource-reader{position:relative;width:min(980px,100%);max-height:92vh;overflow:auto;border-radius:22px;background:#fff;padding:42px;box-shadow:0 28px 80px rgba(0,0,0,.24)}.resource-reader__close{position:absolute;right:22px;top:16px;border:0;background:transparent;font-size:32px;cursor:pointer}.resource-reader header>span{color:var(--color-primary);font-weight:900}.resource-reader header h1{font-size:34px;margin:10px 0}.resource-reader header p{color:#b65d32;line-height:1.7}.resource-reader__meta{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.resource-reader__meta span{border-radius:999px;background:rgba(0,121,102,.08);padding:8px 12px;font-size:13px;font-weight:800}.evidence-list{margin-top:36px;border-top:1px solid rgba(31,54,49,.1);padding-top:24px}.evidence-list article{border-left:3px solid var(--color-primary);background:rgba(0,121,102,.05);margin:12px 0;padding:14px 18px}.evidence-list p{line-height:1.7}.learning-actions{border-top:1px solid rgba(31,54,49,.1);display:grid;gap:14px;margin-top:28px;padding-top:22px}.learning-actions div{display:flex;align-items:center;gap:9px}.learning-actions strong{min-width:90px}.learning-actions button{border:1px solid rgba(0,121,102,.18);border-radius:9px;background:#fff;color:var(--color-primary);cursor:pointer;padding:8px 11px}.learning-actions button.active{background:var(--color-primary);color:#fff}.learning-actions p{color:var(--color-primary);margin:0}
